const adminState = { data: null, orderFilter: {status:'all', date:'', search:''} };
const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
const money = v => `$${Number(v || 0).toFixed(2)}`;
function esc(s){ return String(s ?? '').replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch])); }
function table(headers, rows, empty='No records.'){ return `<table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.join('') : `<tr><td colspan="${headers.length}"><div class="empty-state">${esc(empty)}</div></td></tr>`}</tbody></table>`; }
async function api(path, options={}){
  const headers = {'Content-Type':'application/json'};
  if(adminState.data?.user?.csrf_token) headers['X-CSRF-Token'] = adminState.data.user.csrf_token;
  const res = await fetch(path, {headers, credentials:'same-origin', ...options});
  const json = await res.json().catch(() => ({}));
  if(!res.ok || json.ok === false) throw new Error(json.error || `Request failed ${res.status}`);
  return json;
}
function fileToDataUrl(file){
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Could not read image file.'));
    reader.onload = () => resolve(reader.result);
    reader.readAsDataURL(file);
  });
}
async function loadDashboard(){
  try{
    adminState.data = await api('/api/admin/dashboard');
    $('#adminLoginForm').style.display = 'none';
    renderAll();
  }catch(err){
    $('#adminLoginForm').style.display = '';
    $('#metricGrid').innerHTML = `<div class="warning-box">Admin login required.</div>`;
  }
}
function renderAll(){ renderMetrics(); renderOrders(); renderProduction(); renderProducts(); renderVerification(); renderPhotos(); renderQuotes(); renderPayments(); renderWholesale(); renderCustomers(); renderPromos(); renderForecast(); renderPartners(); renderHours(); renderSeoContent(); renderLaunch(); renderOpsData(); renderCostingGrowth(); renderIntegrations(); renderSecurity(); renderQa(); renderBackups(); renderAudit(); hydrateProductSelects(); }
function hydrateProductSelects(){
  const products = adminState.data?.products || [];
  const options = products.map(p => `<option value="${p.id}">${esc(p.name_es)} / ${esc(p.name_en)} • ${esc(p.slug)}</option>`).join('');
  ['photoProduct','variantProduct','recipeProduct','recipeVerifyProduct'].forEach(id => { const el = $('#'+id); if(el) el.innerHTML = options; });
  const ingredients = adminState.data?.ingredients || [];
  const ingredientOptions = ingredients.map(i => `<option value="${i.id}">${esc(i.name_en)} / ${esc(i.name_es)} • ${esc(i.unit)}</option>`).join('');
  ['recipeIngredient','supplierQuoteIngredient'].forEach(id => { const el=$('#'+id); if(el) el.innerHTML = ingredientOptions; });
  const suppliers = adminState.data?.suppliers || [];
  const supplierOptions = suppliers.map(sp => `<option value="${sp.id}">${esc(sp.name)}</option>`).join('');
  const supplierSelect = $('#supplierQuoteSupplier'); if(supplierSelect) supplierSelect.innerHTML = '<option value="">No supplier selected</option>' + supplierOptions;
}
function renderMetrics(){
  const m = adminState.data.metrics || {}; const h = adminState.data.catalog_health || {};
  const cards = [
    ['Open orders', m.open_orders], ['Today pickups', m.today_pickups], ['Active quotes', m.quote_requests], ['Wholesale pending', m.pending_wholesale], ['Change requests', m.change_requests], ['Reviews pending', m.reviews_pending], ['Open invoices', m.invoices_open], ['Low stock', m.low_stock], ['Needs photos', m.needs_photo], ['Open payments', m.payments_open], ['P0 launch open', m.p0_open], ['30d revenue', money(m.revenue_30d)], ['Verified products', `${h.owner_verified || 0}/${h.active_products || 0}`]
  ];
  $('#metricGrid').innerHTML = cards.map(([label,value]) => `<article class="metric"><span>${label}</span><b>${value}</b></article>`).join('');
}
function renderOrders(){
  const statuses = ['all','received','confirmed','needs_deposit','baking','ready','completed','canceled'];
  $('#ordersToolbar').innerHTML = `<div class="admin-toolbar"><select id="orderStatusFilter">${statuses.map(s=>`<option value="${s}" ${adminState.orderFilter.status===s?'selected':''}>${s}</option>`).join('')}</select><input id="orderDateFilter" type="date" value="${esc(adminState.orderFilter.date)}"><input id="orderSearchFilter" placeholder="Search name, email, phone, code" value="${esc(adminState.orderFilter.search)}"><button id="clearOrderFilters" class="small-button" type="button">Clear</button></div>`;
  $('#orderStatusFilter').onchange = e => { adminState.orderFilter.status=e.target.value; renderOrders(); };
  $('#orderDateFilter').oninput = e => { adminState.orderFilter.date=e.target.value; renderOrders(); };
  $('#orderSearchFilter').oninput = e => { adminState.orderFilter.search=e.target.value.toLowerCase(); renderOrders(); };
  $('#clearOrderFilters').onclick = () => { adminState.orderFilter={status:'all',date:'',search:''}; renderOrders(); };
  let orders = adminState.data.orders || [];
  const f = adminState.orderFilter;
  if(f.status !== 'all') orders = orders.filter(o => o.status === f.status);
  if(f.date) orders = orders.filter(o => o.pickup_date === f.date);
  if(f.search){ orders = orders.filter(o => `${o.order_code} ${o.customer_name} ${o.customer_email} ${o.customer_phone} ${o.business_name}`.toLowerCase().includes(f.search)); }
  const rows = orders.map(o => `<tr><td><b>${esc(o.order_code)}</b><br>${esc(o.customer_name)}<br><small>${esc(o.customer_phone)} ${esc(o.customer_email)} ${esc(o.business_name || '')}</small><br><a href="/receipt?code=${encodeURIComponent(o.order_code)}" target="_blank">Receipt</a> • <a href="/ticket?order_id=${o.id}" target="_blank">Kitchen ticket</a></td><td>${esc(o.pickup_date)}<br>${esc(o.pickup_time)}</td><td>${(o.items||[]).map(i=>`${i.quantity} × ${esc(i.product_name)}${i.variant_summary ? `<br><small>${esc(i.variant_summary)}</small>`:''}`).join('<hr>')}</td><td>${money(o.total)}<br><small>Deposit ${money(o.deposit_due)}</small></td><td><select data-order-status="${o.id}">${['received','confirmed','needs_deposit','baking','ready','completed','canceled'].map(s=>`<option value="${s}" ${o.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="small-button" data-save-status="${o.id}">Save</button></td></tr>`);
  $('#ordersTable').innerHTML = table(['Customer','Pickup','Items','Total','Status'], rows, 'No orders match the filters.');
  $$('[data-save-status]').forEach(btn => btn.addEventListener('click', async () => { const id = btn.dataset.saveStatus; await api('/api/admin/order-status', {method:'POST', body:JSON.stringify({order_id:id,status:$(`[data-order-status="${id}"]`).value})}); await loadDashboard(); }));
}
function renderProduction(){
  const tasks = adminState.data.production_tasks || [];
  const roleLabels = {cashier:'Cashier rush board', baker:'Baker production', decorator:'Cake and seasonal decorator', wholesale_manager:'Wholesale packing'};
  const roleOrder = ['cashier','baker','decorator','wholesale_manager'];
  const taskBoard = roleOrder.map(role => {
    const items = tasks.filter(t => t.assigned_role === role && !['done','canceled'].includes(t.status)).slice(0,40);
    const cards = items.map(t => `<li class="board-task"><b>${esc(t.title)}</b><br><small>${esc(t.order_code || t.quote_code || '')} • ${esc(t.task_type)} • due ${esc(t.due_at || '')}</small><p>${esc(t.public_notes || '')}</p><span class="status-pill ${esc(t.priority)}">${esc(t.priority)}</span> <span class="status-pill ${esc(t.status)}">${esc(t.status)}</span><div class="inline-controls"><select data-task-status="${t.id}">${['todo','doing','blocked','done','canceled'].map(st=>`<option value="${st}" ${t.status===st?'selected':''}>${st}</option>`).join('')}</select><input data-task-notes="${t.id}" placeholder="internal note"><button class="small-button" data-task-save="${t.id}">Save</button></div></li>`).join('');
    return `<article class="board-card"><h3>${roleLabels[role]}</h3><ul>${cards || '<li class="empty-state">No open tasks.</li>'}</ul></article>`;
  }).join('');
  const batchRows = (adminState.data.product_batches || []).slice(0,80).map(b => `<tr><td><b>${esc(b.name_es)}</b><br><small>${esc(b.slug)} • ${esc(b.batch_label)}</small></td><td>${esc(b.batch_date)} ${esc(b.expected_ready_at)}</td><td>${b.produced_qty}</td><td>${b.reserved_qty}</td><td>${b.sold_qty}</td><td>${esc(b.status)}</td></tr>`);
  const seasonalRows = (adminState.data.seasonal_campaigns || []).map(c => `<tr><td><b>${esc(c.title_en)}</b><br><small>${esc(c.slug)} • ${esc(c.status)}</small></td><td>${esc(c.season_start)} → ${esc(c.season_end)}</td><td>${esc(c.preorder_cutoff)}</td><td>${c.max_orders || 'unlimited'}</td><td>${esc(c.pickup_window_notes || '')}</td></tr>`);
  const windowRows = (adminState.data.seasonal_windows || []).slice(0,60).map(w => `<tr><td>${esc(w.title_en)}</td><td>${esc(w.pickup_date)} ${esc(w.starts_at)}-${esc(w.ends_at)}</td><td>${w.capacity}</td><td>${w.reserved_count}</td><td>${esc(w.status)}</td></tr>`);
  const rows = (adminState.data.production_summary || []).map(p => `<tr><td>${esc(p.production_category)}</td><td>${esc(p.product_name)}</td><td><b>${p.quantity}</b></td><td>${esc(p.first_pickup)} → ${esc(p.last_pickup)}</td></tr>`);
  $('#productionSummary').innerHTML = `<h3>Rush board by staff role</h3><div class="board-grid">${taskBoard}</div><hr><h3>Daily bakery case batches</h3>${table(['Product','Ready','Produced','Reserved','Sold','Status'], batchRows, 'No batch rows yet.')}<hr><h3>Seasonal campaigns</h3>${table(['Campaign','Season','Cutoff','Capacity','Pickup notes'], seasonalRows, 'No seasonal campaigns configured.')}<h3>Pickup windows</h3>${table(['Campaign','Window','Capacity','Reserved','Status'], windowRows, 'No seasonal pickup windows configured.')}<hr><h3>Production totals</h3>${rows.length ? table(['Category','Product','Units','Pickup window'], rows) + `<button onclick="window.print()" class="primary-action no-print" type="button">Print production summary</button>` : '<div class="empty-state">No upcoming production orders.</div>'}`;
  $$('[data-task-save]').forEach(btn => btn.addEventListener('click', async () => { const id=btn.dataset.taskSave; await api('/api/admin/production-task-status',{method:'POST', body:JSON.stringify({task_id:id,status:$(`[data-task-status="${id}"]`).value,notes:$(`[data-task-notes="${id}"]`).value})}); await loadDashboard(); }));
}
function renderProducts(){
  const products = adminState.data.products || [];
  const rows = products.map(p => `<tr><td><b>${esc(p.name_es)}</b><br><small>${esc(p.slug)} • ${esc(p.category_key)} • ${esc(p.photo_status)}</small></td><td><input data-product-field="base_price" data-id="${p.id}" type="number" step="0.01" value="${p.base_price ?? ''}"></td><td><input data-product-field="wholesale_price" data-id="${p.id}" type="number" step="0.01" value="${p.wholesale_price ?? ''}"></td><td><input data-product-field="stock_count" data-id="${p.id}" type="number" value="${p.stock_count}"></td><td><select data-product-field="order_mode" data-id="${p.id}">${['order','quote','inactive'].map(x=>`<option value="${x}" ${p.order_mode===x?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-product-field="lead_time_hours" data-id="${p.id}" type="number" value="${p.lead_time_hours}"></td><td><input data-product-field="image_url" data-id="${p.id}" value="${esc(p.image_url || '')}" placeholder="image URL"></td><td><button class="small-button" data-product-save="${p.id}">Save</button></td></tr>`);
  $('#productsTable').innerHTML = table(['Product','Retail','Wholesale','Stock','Mode','Lead hrs','Image',''], rows);
  $$('[data-product-save]').forEach(btn => btn.addEventListener('click', async () => { const id = Number(btn.dataset.productSave); const payload = {id}; $$(`[data-id="${id}"]`).forEach(input => payload[input.dataset.productField] = input.value === '' ? null : input.value); await api('/api/admin/product-update', {method:'POST', body:JSON.stringify(payload)}); await loadDashboard(); }));
}
