  $('#adminLogout').addEventListener('click', async () => { try{ await api('/api/auth/logout',{method:'POST', body:'{}'}); }catch(_){} location.reload(); });
  $('#productCreateForm').addEventListener('submit', async e => { e.preventDefault(); const msg=$('#productCreateMsg'); msg.textContent=''; msg.className='form-message'; try{ await api('/api/admin/product-create',{method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))}); msg.textContent='Product created.'; e.currentTarget.reset(); await loadDashboard(); }catch(err){ msg.className='form-message error'; msg.textContent=err.message; } });
