  $('#eventForm').addEventListener('submit', async e => { e.preventDefault(); const msg=$('#eventMsg'); msg.textContent=''; msg.className='form-message'; try{ await api('/api/admin/event-save',{method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))}); msg.textContent='Event saved.'; e.currentTarget.reset(); await loadDashboard(); }catch(err){ msg.className='form-message error'; msg.textContent=err.message; } });
