    if(e.target?.id === 'staffForm'){ e.preventDefault(); const msg=$('#staffMsg'); msg.className='form-message'; msg.textContent=''; try{ await api('/api/admin/staff-save',{method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))}); msg.textContent='Staff saved.'; e.target.reset(); await loadDashboard(); }catch(err){ msg.className='form-message error'; msg.textContent=err.message; } }
