    if(e.target?.id === 'backupForm'){ e.preventDefault(); const msg=$('#backupMsg'); msg.className='form-message'; msg.textContent=''; try{ const res=await api('/api/admin/backup-run',{method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))}); msg.textContent=`Backup ${res.status}: ${res.file_path || res.message}`; await loadDashboard(); }catch(err){ msg.className='form-message error'; msg.textContent=err.message; } }

