    if(e.target?.id === 'standingGenerateForm'){ e.preventDefault(); const msg=$('#standingGenerateMsg'); msg.className='form-message'; msg.textContent=''; try{ const res=await api('/api/admin/standing-order-generate',{method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))}); msg.textContent=`Generated ${res.created || 0} run(s).`; await loadDashboard(); }catch(err){ msg.className='form-message error'; msg.textContent=err.message; } }
